import random, sys, json
sys.path.insert(0,'/workspace/submission')
sys.path.insert(0,'/workspace/tmp')
import gateway
from harness import *

DIR = {"sip:ember@studio.test": ["sip:e1@alias.studio.test", "tel:+12025550121"],
       "sip:desk@sales.test": ["tel:+12025550122"],
       "sip:trunk@trunk.test": []}
ACC = {"session-k": {"primary": "sip:ember@studio.test", "allow": ["sip:desk@sales.test"]}}
GW = {"edge": {"local_domains": ["studio.test", "sales.test"], "peers": {"edge": ["studio.test"]}},
      "inside": {"local_domains": [], "peers": {"edge": ["studio.test", "sales.test"]}}}
CTX = gateway.Context({"directory": DIR, "accounts": ACC, "gateways": GW})

ALPH = list('abcSIP sip:telT@.<>";,=\\ \t\r\n*-\u00e9\x00\x7f0123456789!%~`\'+()_&/?{}[]^') + ['SIP:','tel:','sip:','INVITE','MESSAGE','SIP/2.0','From:','To:','Call-ID:','CSeq:','Content-Length:','P-Asserted-Identity:','Privacy:','\r\n\r\n','\r\n']
def rnd_text(n):
    return "".join(random.choice(ALPH) for _ in range(n))

def structured():
    parts = []
    m = random.choice(["MESSAGE","INVITE","OPTIONS","message"])
    ruri = random.choice(["sip:i@r.t","sip:%65mber@STUDIO.TEST.","tel:+12025550121","sip:@x","sip:x","sips:x@y",""])
    parts.append("%s %s SIP/2.0%s" % (m, ruri, random.choice(["",""," ","\t"])))
    names = ["From","To","from","f","t","i","l","c","Call-ID","CSeq","Content-Length","P-Asserted-Identity","P-Preferred-Identity","Remote-Party-ID","Privacy","Content-Type","X","Via","Authorization","Contact",""]
    vals = ["<sip:ember@studio.test>","sip:e1@alias.studio.test","<tel:+12025550121>","\"a\"<sip:desk@sales.test>","<>","<sip:x@y>",
            "< sip:trunk@trunk.test >","Alice <sip:ember@studio.test>","<sip:anonymous@anonymous.invalid>","<sip:ember@studio.test>;tag=q",
            "<sip:ember@studio.test> ; TAG = q ","<sip:ember@studio.test>;tag=","1","id","NONE","text/plain","","<sip:a@b>,<tel:+12025550122>",
            "<sip:a@b>,<sip:c@d>","<sip:a@b.c> <sip:d@e.f>","\"unterm","<sip:a%40b@studio.test>","<sip:a@-b.com>","<sip:a@b.com.>",
            "a"*130, "<sip:a@b.com>;tag=" + "t"*129, "<sip:a@b.com>;", "0009","0"]
    nl = random.randint(0,10)
    lines = []
    for k in range(nl):
        nm = random.choice(names); vl = random.choice(vals)
        sep = random.choice([": ",":",":  "," : ", "\t:\t"])
        lines.append(nm+sep+vl)
        if random.random()<0.2: lines.append("  "+random.choice(vals))
    body = random.choice(["hello","","a\r\nb","x"*random.randint(1,50)])
    head = m+" "+ruri+" SIP/2.0"
    text = head + "\r\n" + "".join(l+"\r\n" for l in lines)
    if random.random()<0.9:
        text += "\r\n" + body
    text = text.replace("Content-Length", "Content-Length")
    return text

def structured_cl_fixed():
    """like structured but with correct Content-Length"""
    t = structured()
    i = t.find("\r\n\r\n")
    if i < 0: return t
    head, body = t[:i], t[i+4:]
    import re
    head = re.sub(r"Content-Length:[^\r\n]*", "Content-Length: %d" % len(body), head)
    return head + "\r\n\r\n" + body

internal = []
stats = {"reject":{}, "accept":0}
random.seed(11)
for trial in range(60000):
    style = random.random()
    if style < .35:
        text = rnd_text(random.randint(0,60))
    elif style < .7:
        text = structured_cl_fixed()
    else:
        text = structured()
    gw = random.choice(["edge","inside","nope"])
    ing = random.choice([{"kind":"local","subject":"session-k"},{"kind":"local","subject":"nope"},
                         {"kind":"peer","name":"edge"},{"kind":"peer","name":"nope"},{"kind":"untrusted"}])
    job = {"gateway":gw, "ingress":ing, "trusted_out":random.random()<.5, "raw":text}
    try:
        res = gateway.handle(job, 0, [], CTX)
    except gateway.Reject as exc:
        if exc.reason not in ("syntax","unauthenticated","identity","upstream"):
            internal.append(("bad reason", exc.reason, text))
        stats["reject"][exc.reason] = stats["reject"].get(exc.reason,0)+1
        continue
    except Exception as exc:
        internal.append((type(exc).__name__, str(exc), text))
        continue
    stats["accept"] += 1
    # invariants on accepted wire
    w = res["wire"]
    if "\r\n\r\n" not in w: internal.append(("no divider", res, text))
    elif w.find("\r\n\r\n") != w.rfind("\r\n\r\n") and not w[w.find("\r\n\r\n")+4:].startswith("\r\n"):
        pass
    lines = w.split("\r\n")
    try:
        cut = w.index("\r\n\r\n")
    except ValueError:
        internal.append(("bad wire", res, text)); continue
    hdrs = w[:cut].split("\r\n"); body = w[cut+4:]
    if not hdrs[0].endswith(" SIP/2.0"): internal.append(("rline", res, text))
    names = [h.split(":")[0].lower() for h in hdrs[1:]]
    want = ["from","to","call-id","cseq","privacy"]
    if body: want.append("content-length")
    if names[:len(want)] != want: internal.append(("order", names, text))
    if hdrs[-1] != "Content-Length: %d" % len(body): internal.append(("cl", hdrs[-1], len(body), text))
    if res["private"] != ("<sip:anonymous@anonymous.invalid>" in w): internal.append(("private/from", res, text))
    if res["identity"] not in DIR: internal.append(("identity", res, text))
    # reparse the accepted wire at the same gateway/ingress: must be a fixed point
    job2 = {"gateway":"edge","ingress":{"kind":"local","subject":"session-k"},"trusted_out":True,"raw":w}
    try:
        res2 = gateway.handle(job2, 0, [], CTX)
    except gateway.Reject as exc:
        internal.append(("reparse reject %s" % exc.reason, res, text)); continue
    except Exception as exc:
        internal.append(("reparse crash", type(exc).__name__, text)); continue
print("stats", stats)
print("internal problems:", len(internal))
seen = set()
for p in internal[:25]:
    key = p[0]
    if key in seen: continue
    seen.add(key)
    print(json.dumps(p)[:400])
PYEOF
